import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Stats Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/characters/stats.md","filePath":"guide/characters/stats.md"}'),o={name:"guide/characters/stats.md"};function i(n,e,d,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="stats-overview" tabindex="-1">Stats Overview <a class="header-anchor" href="#stats-overview" aria-label="Permalink to &quot;Stats Overview&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> These are intended changes, not confirmed live rules. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/characters/stats.html">full design specification</a>.</p><h2 id="responsiveness-comes-first" tabindex="-1">Responsiveness comes first <a class="header-anchor" href="#responsiveness-comes-first" aria-label="Permalink to &quot;Responsiveness comes first&quot;">​</a></h2><p>Low stats should not make normal control feel like slow motion. In the proposed redesign, a new character with low DEX should still attack at a believable cadence. That goal has not yet changed the game&#39;s attack timing.</p><h2 id="what-each-stat-could-contribute" tabindex="-1">What each stat could contribute <a class="header-anchor" href="#what-each-stat-could-contribute" aria-label="Permalink to &quot;What each stat could contribute&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stat</th><th>Proposed role</th></tr></thead><tbody><tr><td>DEX</td><td>Bounded recovery, control, balance, aim correction and responsiveness under pressure</td></tr><tr><td>STR</td><td>Handling heavy weapons or armor, load, endurance and demanding physical actions</td></tr><tr><td>INT</td><td>Cognitive workspace for Active Memory and complex patterns, alongside unresolved mental/resource relationships</td></tr></tbody></table><p>DEX should not dominate basic attack cadence. STR should not simply multiply every weapon&#39;s damage, and INT should be more than mana size. Exact effects, stat ranges, total cap and gain rules remain undecided.</p><h2 id="stats-support-expertise" tabindex="-1">Stats support expertise <a class="header-anchor" href="#stats-support-expertise" aria-label="Permalink to &quot;Stats support expertise&quot;">​</a></h2><p>STR may help you handle a heavy hammer, but weapon skill and technique should define expertise. DEX can support shooting control while Archery and player execution matter. INT can support magical capability while Magery, Meditation and knowledge define what you can do.</p><p>Weapon behavior, techniques, recovery and stamina should matter to combat rhythm. Responsive-looking animation must not secretly create extra attacks; combat outcomes and opportunities stay with the server.</p><p><a href="/Syrolands-Public/guide/characters/progression.html">Progression</a> · <a href="/Syrolands-Public/guide/characters/skills.html">Skills</a> · <a href="/Syrolands-Public/guide/combat/overview.html">Combat overview</a></p><h2 id="int-and-prepared-magic" tabindex="-1">INT and prepared magic <a class="header-anchor" href="#int-and-prepared-magic" aria-label="Permalink to &quot;INT and prepared magic&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/magic/memory-and-familiarity.html">Spell Memory and Familiarity</a> explains the Proposed cognitive role: knowing a spell is different from preparing it for immediate access to normal casting. Memory counts, complexity costs and the relationship to mana remain undecided.</p>',13)])])}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
